head.script:
scwin.screenId = "jlddst35300";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst35300.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_fnSearch_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnSearch_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnSearch(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst35300.btn_fnSearch_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_goToPageList_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goToPageList_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goToPageList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goToPageList('','','',''); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst35300.btn_goToPageList_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/disclosureinfo/regulationsystem.do",
        ref: "dma_fnSearchReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst35300.tx_fnSearch" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_goToPageList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_goToPageList = async function () {
    const sbmOptions = {
        id: "tx_goToPageList",
        method: "post",
        action: "/disclosureinfo/regulationsystem.do",
        ref: "dma_goToPageListReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst35300.tx_goToPageList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.replaceKeyword
 * @author Inswave
 * @date 2026. 09. 29
 * @param _srcStr _keyword
 * @returns
 * @hidden N
*/
scwin.replaceKeyword = function (_srcStr, _keyword) {
    /* sdd-asis-lifecycle:begin fn_ReplaceKeyword — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    document.write(_srcStr.replace(new RegExp(_keyword, "g"), "<span class='search'>" + _keyword + "</span>"));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_fnSearchReq').set('method', "searchRegulationSystemSub");
    $c.util.getComponent('dma_fnSearchReq').set('forward', "regulationsystem_sub1");
    (document.frm || { elements: [] }).target = "iframe";
    (document.frm || { elements: [] }).action = "/disclosureinfo/regulationsystem.do";
    await scwin.tx_fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goToPageList
 * @author Inswave
 * @date 2026. 09. 29
 * @param lawNo lawTitle dtruleLawNo lawAmendDd
 * @returns
 * @hidden N
*/
scwin.goToPageList = async function (lawNo, lawTitle, dtruleLawNo, lawAmendDd) {
    /* sdd-asis-lifecycle:begin goToPageList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_fnSearchReq').set('lawNo', lawNo);
    $c.util.getComponent('dma_fnSearchReq').set('lawTitle', lawTitle);
    $c.util.getComponent('dma_fnSearchReq').set('dtruleLawNo', dtruleLawNo);
    $c.util.getComponent('dma_fnSearchReq').set('lawAmendDd', lawAmendDd);
    $c.util.getComponent('dma_fnSearchReq').set('lawNo', lawNo);
    $c.util.getComponent('dma_fnSearchReq').set('method', "searchRegulationItem");
    $c.util.getComponent('dma_fnSearchReq').set('forward', "regulationsystem_sub2");
    (document.frm || { elements: [] }).target = "iframe";
    (document.frm || { elements: [] }).action = "/disclosureinfo/regulationsystem.do";
    await scwin.tx_goToPageList();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            await scwin.fnSearch();
        }
    }
    /* sdd-asis-lifecycle:end */
};
